insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Más sobre Bolton$vn$), $vn$WHYES-005$vn$, $vn$Summary$vn$, $vn$Entonces, en resumen, tu Bienestar Financiero de Bolton incluye todo lo que te protege legal y financieramente. Primero que nada, tu nuevo pago de $XXX al mes te ahorra muchísimo dinero, sin siquiera contar todos los intereses que estás ahorrando. Ninguna otra compañía está dispuesta a invertir el tiempo y el dinero en tu éxito. Escucho historias de éxito todo el tiempo que me dejan impresionado. A Bolton realmente le importa primero ser buena gente. Ahora por fin puedes decir que encontraste una solución en la que puedes confiar. Y eso es lo que realmente importa, ¿verdad?$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "Entonces, en resumen, tu Bienestar Financiero de Bolton incluye todo lo que te protege legal y financieramente. Primero que nada, tu nuevo pago de $XXX al mes te ahorra muchísimo dinero, sin siquiera contar todos los intereses que estás ahorrando. Ninguna otra compañía está dispuesta a invertir el tiempo y el dinero en tu éxito. Escucho historias de éxito todo el tiempo que me dejan impresionado. A Bolton realmente le importa primero ser buena gente. Ahora por fin puedes decir que encontraste una solución en la que puedes confiar. Y eso es lo que realmente importa, ¿verdad?"}]$vn$::jsonb, null, null, null, 50, $vn$This is the emotional peak before the mechanics start. Build through it and land on trust. Then stop and let them agree.$vn$, $vn$I have found something I can trust.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-001$vn$, $vn$How Today Goes$vn$, $vn$Entonces, empezar es súper sencillo. Elegimos una fecha de pago que te funcione, voy a ingresar tu información bancaria, lo cual me permite enviarte el acuerdo por correo electrónico - lo vamos a revisar juntos - solamente toma unos 10 minutos. Cuando terminemos ahí, te voy a presentar a tu coach financiero certificado y eso será todo por hoy.$vn$, array[$vn$CALM$vn$]::text[], $vn$[{"tone": "CALM", "text": "Entonces, empezar es súper sencillo. Elegimos una fecha de pago que te funcione, voy a ingresar tu información bancaria, lo cual me permite enviarte el acuerdo por correo electrónico - lo vamos a revisar juntos - solamente toma unos 10 minutos. Cuando terminemos ahí, te voy a presentar a tu coach financiero certificado y eso será todo por hoy."}]$vn$::jsonb, null, null, null, 10, $vn$Calm and procedural. You are describing something routine that you do every day. Any urgency here reads as pressure.$vn$, $vn$This is easy and almost over.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-002$vn$, $vn$What Happens Next$vn$, $vn$En el próximo día o dos vas a escuchar de Slate para darte orientación inmediata. Y un par de días después tendrás tu primera reunión formal con tu coach, pero ustedes dos van a programarla al final de la llamada de hoy. ¿Te parece bien?$vn$, array[]::text[], $vn$[{"tone": "", "text": "En el próximo día o dos vas a escuchar de Slate para darte orientación inmediata. Y un par de días después tendrás tu primera reunión formal con tu coach, pero ustedes dos van a programarla al final de la llamada de hoy. ¿Te parece bien?"}]$vn$::jsonb, null, null, null, 20, $vn$Keep the same calm register. Setting a clear timeline here is what stops the anxious call on day three.$vn$, $vn$I know exactly what happens after we hang up.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-003$vn$, $vn$Lock The Date$vn$, $vn$Lo más pronto que podría programar tu primer pago es mañana, ¿te funciona?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Lo más pronto que podría programar tu primer pago es mañana, ¿te funciona?"}]$vn$::jsonb, null, $vn$(Asegura una fecha y sigue adelante)$vn$, null, 30, $vn$Ask it plainly and then be completely silent. Lock a date and move on. Do not restate it or soften it.$vn$, $vn$This is a simple scheduling question.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-004$vn$, $vn$Banking Information$vn$, $vn$Será un pago automático cada mes, así que para ese pago, ¿con qué banco trabajas? Y el número de ruta y número de cuenta. Gracias. (Cliente) Tu correo electrónico es, xxxxx ¿correcto?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Será un pago automático cada mes, así que para ese pago, ¿con qué banco trabajas? Y el número de ruta y número de cuenta. Gracias. (Cliente) Tu correo electrónico es, xxxxx ¿correcto?"}]$vn$::jsonb, null, $vn$(Recopila información ACH)$vn$, null, 40, $vn$Businesslike, unhurried, no hesitation in your voice. Hesitation here tells them to hesitate too.$vn$, $vn$This is a normal transaction.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-005$vn$, $vn$Chirp Heads Up$vn$, $vn$¡Excelente, gracias por eso! Solo un aviso rápido: durante tu conversación con tu coach financiero, van a explicarte un servicio llamado Chirp sin costo adicional. Chirp ayuda a que los pagos se procesen de manera más fluida durante todo el programa y elimina cualquier cargo por sobregiro o pago devuelto si alguna vez el tiempo se vuelve un problema. Solo quería mencionártelo de antemano.$vn$, array[]::text[], $vn$[{"tone": "", "text": "¡Excelente, gracias por eso! Solo un aviso rápido: durante tu conversación con tu coach financiero, van a explicarte un servicio llamado Chirp sin costo adicional. Chirp ayuda a que los pagos se procesen de manera más fluida durante todo el programa y elimina cualquier cargo por sobregiro o pago devuelto si alguna vez el tiempo se vuelve un problema. Solo quería mencionártelo de antemano."}]$vn$::jsonb, null, null, null, 50, $vn$Light and passing. This is a courtesy note, so treat it as one. Making it a big deal makes them wonder why.$vn$, $vn$That is useful and no additional cost.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$El cierre$vn$), $vn$ENRES-006$vn$, $vn$Send The Email$vn$, $vn$Gracias (Nombre del Cliente), te voy a enviar un correo electrónico que vendrá de Bolton Services Group, avísame cuando lo recibas.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Gracias (Nombre del Cliente), te voy a enviar un correo electrónico que vendrá de Bolton Services Group, avísame cuando lo recibas."}]$vn$::jsonb, null, null, null, 60, $vn$Short and clear. Then wait for them to confirm before you say anything else.$vn$, $vn$I know what to look for.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-001$vn$, $vn$Open The Portal$vn$, $vn$¿Estás frente a una computadora, teléfono inteligente o Tablet? Abre el correo electrónico que te envié y haz clic en el enlace azul. Esto abrirá el Portal del Cliente. Vas a ver dos documentos, por favor haz clic en el círculo rojo del primero. El documento tardará un minuto en cargar. Avísame cuando veas el documento.$vn$, array[]::text[], $vn$[{"tone": "", "text": "¿Estás frente a una computadora, teléfono inteligente o Tablet? Abre el correo electrónico que te envié y haz clic en el enlace azul. Esto abrirá el Portal del Cliente. Vas a ver dos documentos, por favor haz clic en el círculo rojo del primero. El documento tardará un minuto en cargar. Avísame cuando veas el documento."}]$vn$::jsonb, null, $vn$Envía la información de inicio de sesión del Portal del Cliente (el cliente firmará el acuerdo a través de ahí)$vn$, $vn$Abrir el portal$vn$, 10, $vn$One instruction at a time and wait after each. Racing ahead of where they actually are is what turns a ten minute signing into thirty.$vn$, $vn$He is going at my speed.$vn$, false, 'published');
